describe('Column Visibility Toggle', () => {
  beforeEach(() => {
    cy.visit('/table');
    cy.get('[data-testid="table-container"]').should('be.visible');
  });

  it('should toggle column visibility from settings menu', () => {
    // Open settings menu
    cy.get('[data-testid="settings-menu-button"]').click();
    cy.get('[data-testid="settings-menu"]').should('be.visible');

    // Verify initial column visibility
    cy.get('[data-testid="column-header-name"]').should('be.visible');
    cy.get('[data-testid="column-header-email"]').should('be.visible');
    cy.get('[data-testid="column-header-phone"]').should('be.visible');

    // Toggle email column off
    cy.get('[data-testid="toggle-column-email"]').click();
    cy.get('[data-testid="column-header-email"]').should('not.be.visible');

    // Verify other columns remain visible
    cy.get('[data-testid="column-header-name"]').should('be.visible');
    cy.get('[data-testid="column-header-phone"]').should('be.visible');

    // Toggle email column back on
    cy.get('[data-testid="toggle-column-email"]').click();
    cy.get('[data-testid="column-header-email"]').should('be.visible');

    // Close settings menu
    cy.get('[data-testid="settings-menu-close"]').click();
    cy.get('[data-testid="settings-menu"]').should('not.be.visible');
  });

  it('should persist column visibility preferences after page reload', () => {
    // Open settings menu
    cy.get('[data-testid="settings-menu-button"]').click();

    // Hide multiple columns
    cy.get('[data-testid="toggle-column-phone"]').click();
    cy.get('[data-testid="toggle-column-address"]').click();

    // Close settings menu
    cy.get('[data-testid="settings-menu-close"]').click();

    // Verify columns are hidden
    cy.get('[data-testid="column-header-phone"]').should('not.be.visible');
    cy.get('[data-testid="column-header-address"]').should('not.be.visible');
    cy.get('[data-testid="column-header-name"]').should('be.visible');

    // Reload page
    cy.reload();

    // Verify preferences are persisted
    cy.get('[data-testid="column-header-phone"]').should('not.be.visible');
    cy.get('[data-testid="column-header-address"]').should('not.be.visible');
    cy.get('[data-testid="column-header-name"]').should('be.visible');
  });

  it('should handle toggling all columns off and back on', () => {
    // Open settings menu
    cy.get('[data-testid="settings-menu-button"]').click();

    // Get all column toggles
    cy.get('[data-testid^="toggle-column-"]').each(($toggle) => {
      cy.wrap($toggle).click();
    });

    // Verify all columns are hidden
    cy.get('[data-testid^="column-header-"]').should('not.exist');

    // Toggle all columns back on
    cy.get('[data-testid^="toggle-column-"]').each(($toggle) => {
      cy.wrap($toggle).click();
    });

    // Verify all columns are visible
    cy.get('[data-testid="column-header-name"]').should('be.visible');
    cy.get('[data-testid="column-header-email"]').should('be.visible');
    cy.get('[data-testid="column-header-phone"]').should('be.visible');
  });

  it('should update table data rows when columns are toggled', () => {
    // Verify initial row structure
    cy.get('[data-testid="table-row-0"]').within(() => {
      cy.get('[data-testid="cell-name"]').should('be.visible');
      cy.get('[data-testid="cell-email"]').should('be.visible');
    });

    // Open settings and hide email column
    cy.get('[data-testid="settings-menu-button"]').click();
    cy.get('[data-testid="toggle-column-email"]').click();

    // Verify email cells are hidden in rows
    cy.get('[data-testid="table-row-0"]').within(() => {
      cy.get('[data-testid="cell-name"]').should('be.visible');
      cy.get('[data-testid="cell-email"]').should('not.be.visible');
    });

    // Close menu
    cy.get('[data-testid="settings-menu-close"]').click();
  });
});
